import { componentAttrs } from "../_utils/component.helper";

function esc(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function resolveLink(link) {
  if (!link) return null;
  if (typeof link === "string") return { url: link, target: "_self" };
  if (typeof link === "object" && link.url)
    return { url: link.url, target: link.target || "_self" };
  return null;
}

/**
 * Font Awesome classic/thin, per this project's icon convention -- not an
 * inline SVG. The shared .button primitive's own `i:empty` rule (see
 * buttons.css) handles sizing/layout for an empty <i> automatically.
 */
const ICON_SVG =
  '<i class="floating-button__icon fa-thin fa-arrow-right" aria-hidden="true"></i>';

export default {
  async main(input = {}) {
    const {
      label = "Label",
      link = null,
      ariaLabel = "",
      landmarkLabel = "Floating action button",
    } = input;

    const actionClass = "floating-button__action button";

    const ariaLabelAttr =
      ariaLabel && ariaLabel !== label ? ` aria-label="${esc(ariaLabel)}"` : "";

    const resolved = resolveLink(link);
    const content = `<span data-sq-field="label">${esc(label)}</span>${ICON_SVG}`;

    const actionHtml = resolved
      ? `<a class="${actionClass}" href="${esc(resolved.url)}"${resolved.target !== "_self" ? ` target="${esc(resolved.target)}" rel="noopener noreferrer"` : ""}${ariaLabelAttr}>${content}</a>`
      : `<button type="button" class="${actionClass}"${ariaLabelAttr}>${content}</button>`;

    return /*html*/ `
<div ${componentAttrs("floating-button", input)} class="fullwidth" role="complementary" aria-label="${esc(landmarkLabel)}">
  <div class="floating-button__container">
    <div class="floating-button__button-wrapper">
      ${actionHtml}
    </div>
  </div>
</div>
`;
  },
};
